  ('02｜1F バーとラウンジ','会員交流のための会員専用バー',['1階には会員専用のバーがあります。「会員交流を促進する会員専用バー」と説明されています。','ラウンジは催しにも向く場所で、ワンダーゾーンは中規模のイベントも開けるフリースペースです。'],[(4,'館内の風景'),(5,'館内の風景')]),
  ('03｜B1F 御座敷とフリーワーク','畳の上で自由に考える',['地下1階のフリーワークスペースは「自由に働けるエリア、ブースも多数配置」。御座敷は「自由な発想が生まれる畳スペース」です。','会員が使える会議室は4部屋。靴を脱いで座る場所が、都心のオフィスビルの地下にあります。'],[(6,'館内の風景')]),
  ('04｜4F 固定席と個室','法人登記のできる専用デスク',['4階の固定席は「法人登記も可能な専用デスク」で、月77,000円の固定ブースと、月33,000円のフリーデスクがあります。個室は「4人まで入居可能な家具付き専用個室」で、料金は問い合わせです。','コミュニティ会員は月16,500円。席を持たずに、交流と催しに加わる入口です。'],[(7,'SPACE の紹介写真')]),
