 facts=[('施設','MIDORI.so NAGATACHO'),('場所','東京都千代田区平河町 2-5-3'),('構成','地下1階〜6階の7フロア、約23,000 sq. ft.（公式サイトの表記）'),('規模','1人〜150人のチームまで'),('運営','MIRAI INSTITUTE株式会社')],
