_DROP_FACE3 = {'wework-hanzomon-prex-north': [2, 3, 4, 5], 'wework-tokyo-portcity-takeshiba': [1, 3, 6], 'wework-kdx-toranomon-1chome': [1, 2, 3, 4, 7],
  'co-lab-daikanyama': [4], 'startup-hub-tokyo-marunouchi': [1, 2, 5, 6, 7, 8], 'chiyoda-platform-square': [4], 'city-lab-tokyo': [1, 3, 6],
  'case-shinjuku': [3, 6, 8], 'merise-tachikawa': [1], 'mov-kuramae': [8], 'ryozan-park-sugamo-grand': [1, 2, 6, 8]}
A30[:] = [a for a in A30 if a['slug'] not in _HOLD_FACE3]
for _a in A30:
    _s = _a['slug']
    if _s not in _DROP_FACE3: continue
    for _n in _DROP_FACE3[_s]: IMG30[_s].pop(str(_n), None)
    _st = [(st[0], st[1], st[2], [p for p in st[3] if p[0] not in _DROP_FACE3[_s]]) for st in _a['steps']]
    _st = [st for st in _st if st[3]]
    _a['steps'] = [(_re.sub(r'^\d+', '%02d' % (i + 1), st[0]),) + tuple(st[1:]) for i, st in enumerate(_st)]
    _a['photo_total'] = len(IMG30[_s])
    if str(_a['hero'][0]) not in IMG30[_s]:
        _h = next(p[0] for st in _a['steps'] for p in st[3])
        _a['hero'] = (_h, next((p[1] for st in _a['steps'] for p in st[3] if p[0] == _h), '館内の様子'))

